+fn heartbeat_publication_failure_keeps_mute_and_ordinary_actions_serving() {
+    let light = Arc::new(Mutex::new(lamp_msgs::Light {
+        on: false,
+        colour: "white".into(),
+        level: 2,
+    }));
+    let (mut running, _) = Running::prepared_outputs(
+        true,
+        false,
+        false,
+        50,
+        false,
+        false,
+        Some(WorkingLight(light.clone())),
+    );
+    let (entered, release) = running.control.block(Edge::Read);
+    running.clock.store(1_000_000, Ordering::Release);
+    let previous = entered
+        .recv_timeout(Duration::from_secs(2))
+        .expect("heartbeat entered the mixer read")
+        .unwrap();
+    assert_eq!(previous.volume_raw, Some(50));
+    // Fail publication without removing the retained positive snapshot. This
+    // exposes the old snapshot's exact freshness bound after failed revocation.
+    let writing = running
+        .bus
+        .root()
+        .join(SpeakerState::TOPIC)
+        .join(format!(".latest.{}.new", previous.session_id));
+    std::fs::create_dir(&writing).unwrap();
+    let queued = queue(
+        &running.dir,
+        json!({"op":"call","name":"not_a_tool","args":{}}),
+    )
+    .unwrap();
+    release.send(()).unwrap();
+    let reply = receive(queued);
+    assert!(
+        reply.is_ok(),
+        "Actions stopped after the heartbeat's speaker publication failure: {reply:?}"
+    );
+    assert_eq!(reply.unwrap()["ok"], false);
+    assert_eq!(running.control.reads.load(Ordering::Acquire), 2);
+    // The heartbeat has completed and the server crossed a call boundary;
+    // mute cannot win a race against the failing heartbeat in this test.
     assert_eq!(running.ask("volume_mute", json!({}))["ok"], true);
     assert_eq!(running.control.level.load(Ordering::Acquire), 0);
-    assert!(running.finish().is_err());
+    assert_eq!(running.control.writes.load(Ordering::Acquire), 1);
+    assert!(running.dir.join(READY_FILE).exists());
+    assert!(running.dir.join(CALL_SOCKET).exists());
+    assert_eq!(running.ask("volume_unmute", json!({}))["ok"], true);
+    assert_eq!(running.control.level.load(Ordering::Acquire), 50);
+    assert_eq!(running.ask("light_on", json!({}))["ok"], true);
+    assert!(light.lock().unwrap().on);
+
+    std::fs::remove_dir(&writing).unwrap();
+    assert_eq!(running.ask("volume_to", json!({"volume":30}))["ok"], true);
+    assert_eq!(running.control.level.load(Ordering::Acquire), 30);
+    let reads = running.control.reads.load(Ordering::Acquire);
+    running.clock.store(30_000_000, Ordering::Release);
+    running.ask("not_a_tool", json!({}));
+    assert_eq!(running.control.reads.load(Ordering::Acquire), reads);
