+        assert!(
+            SpeakerState::from_message(
+                &retained,
+                "fixture-host",
+                previous.stamp.at_us + age,
+                retained.header.at_unix_ms + age / 1000,
+            )
+            .is_ok()
+        );
+    }
+    assert!(
+        SpeakerState::from_message(
+            &retained,
+            "fixture-host",
+            previous.stamp.at_us + lamp_msgs::SPEAKER_STATE_FRESH_US,
+            retained.header.at_unix_ms,
+        )
+        .is_err()
+    );
+    assert!(running.finish().is_ok());
